import{_ as e,o as a,c as o,a3 as i}from"./chunks/framework.DMtjdCb-.js";const d="/help/assets/collection-detail.DePfYL4j.png",s="/help/assets/external-folders.vg2GsQiZ.svg",l="/help/assets/collection-editions.B_3YABuH.png",r="/help/assets/relationship-graph.DBal-MPi.png",u=JSON.parse('{"title":"7. 使用已有收藏","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/collections.md","filePath":"zh-Hans/collections.md"}'),n={name:"zh-Hans/collections.md"};function c(h,t,p,m,g,_){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="_7-使用已有收藏" tabindex="-1">7. 使用已有收藏 <a class="header-anchor" href="#_7-使用已有收藏" aria-label="Permalink to &quot;7. 使用已有收藏&quot;">​</a></h1><p>硬盘上已经有动画时，可以保留现有目录结构接入 AnimeMachine。普通标题目录、较深的子目录，以及 DVD / BD、多资源组并存的收藏都可识别；播放时按作品选择来源和版本。</p><h2 id="先选择接入方式" tabindex="-1">先选择接入方式 <a class="header-anchor" href="#先选择接入方式" aria-label="Permalink to &quot;先选择接入方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想实现什么？</th><th>使用的设置</th></tr></thead><tbody><tr><td>浏览和播放现有收藏，保留原有目录</td><td><strong>映射外部只读媒体库</strong></td></tr><tr><td>让 AnimeMachine 整理新下载的收藏</td><td><strong>动画收藏库路径</strong></td></tr><tr><td>查看 Ani-RSS 下载的媒体</td><td>Ani-RSS 的媒体目录或远程媒体功能</td></tr></tbody></table><p>已有大量媒体时，可先以外部只读方式接入，确认识别和播放结果后，再考虑需要的整理操作。</p><h2 id="添加已有媒体目录" tabindex="-1">添加已有媒体目录 <a class="header-anchor" href="#添加已有媒体目录" aria-label="Permalink to &quot;添加已有媒体目录&quot;">​</a></h2><ol><li>打开 <strong>设置 → 连接</strong>。</li><li>启用 <strong>映射外部只读媒体库</strong>，填写程序能访问的媒体目录。</li><li>保存设置，等待后台完成文件清点。</li><li>搜索其中一部作品，打开详情，在播放区查看来源与集数。</li></ol><p><img src="'+d+'" alt="已有收藏：查看已识别的来源与集数" loading="lazy"></p><p>扫描会进入子目录，区分正片与 NCOP / NCED、预告等特典。目录或文件名应包含可辨认的作品名称、季度或集数；信息不足时可在详情核对识别结果。</p><h2 id="docker-folders" tabindex="-1">Docker 的两种路径 <a class="header-anchor" href="#docker-folders" aria-label="Permalink to &quot;Docker 的两种路径 {#docker-folders}&quot;">​</a></h2><p>Docker 需要先把 NAS 目录挂入容器，再在设置中填写容器路径。例如：</p><table tabindex="0"><thead><tr><th>NAS 上的目录</th><th>容器看到的目录</th><th>设置中填写</th></tr></thead><tbody><tr><td><code>/volume1/anime</code></td><td><code>/External</code></td><td><code>/External</code></td></tr><tr><td>项目内 <code>library</code></td><td><code>/Library</code></td><td><code>/Library</code></td></tr></tbody></table><p><img src="'+s+'" alt="目录示意：NAS 目录与容器路径的对应关系" loading="lazy"></p><p>默认组合可在 <code>compose.yaml</code> 同目录新建 <code>.env</code>，填写已有媒体目录：</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ANM_EXTERNAL_LIBRARY_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/volume1/anime</span></span></code></pre></div><p>然后在该目录运行 <code>docker compose up -d</code>，再到 AnimeMachine 中启用对应的外部媒体库。<code>/volume1/anime</code> 是示例，需要替换成 NAS 文件管理器中真实的目录。</p><p>Windows 可直接填写 <code>C:\\Anime</code> 或 <code>\\\\NAS\\Anime</code>；网络共享需要能被运行 AnimeMachine 的 Windows 账号访问。路径下方显示读取或休眠状态，改动后先保存再检查。</p><h2 id="选择播放版本" tabindex="-1">选择播放版本 <a class="header-anchor" href="#选择播放版本" aria-label="Permalink to &quot;选择播放版本&quot;">​</a></h2><ol><li>打开已识别作品的详情。</li><li>先选择媒体来源，再在版本下拉框选择资源组、DVD / BD、画质等版本。</li><li>核对可播放的集数，点击播放器按钮。</li></ol><p><img src="'+l+'" alt="版本选择：DVD、BD 或多个资源组分别查看" loading="lazy"></p><p><strong>完成标志：</strong> 播放区显示该版本的集数，播放器打开选定版本。选择“自动选择”时由程序为各集选择合适的可用版本。</p><h2 id="未显示已有文件" tabindex="-1">未显示已有文件 <a class="header-anchor" href="#未显示已有文件" aria-label="Permalink to &quot;未显示已有文件&quot;">​</a></h2><p>首次扫描期间，播放区会显示索引准备状态。若扫描结束后仍缺少文件，先检查 <strong>设置 → 连接</strong> 中的路径、挂载与可读状态，再核对作品标题和文件命名。磁盘休眠或暂时断线时，已有索引会保留，恢复可访问后继续使用。</p><h2 id="查看作品关系" tabindex="-1">查看作品关系 <a class="header-anchor" href="#查看作品关系" aria-label="Permalink to &quot;查看作品关系&quot;">​</a></h2><p>点击作品卡片上的 <strong>作品关系图</strong>，查看前作、续作、剧场版和番外。打开后会定位到当前作品；点击图中标题可打开详情。关系类型可切换显示，也可全屏查看或导出图片。</p><p><img src="'+r+'" alt="作品关系图" loading="lazy"></p>',26)])])}const k=e(n,[["render",c]]);export{u as __pageData,k as default};
